entries[200118] = { ["name"] = "Gelber Späherottuk", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei den Tuskarr von Iskaara.\n\n\"Gelbe Späherottuks lieben es, sich zu verstecken und mit ihrer Umgebung zu verschmelzen. Wenn sie nicht gerade Verstecken mit ihren Reitern \"spielen\", sind sie die perfekten Begleiter beim Ausspähen feindlicher Lager.\"\nFraktion:\nTuskarr von Iskaara\nRuhmstufe:\n25\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n2\n2\n750" }
entries[200119] = { ["name"] = "Immerbrennendes Feuerherz", ["text"] = "Questgegenstand\nEinzigartig\n\"Es heißt, Firavas Herz sei an diesem Tag dank der Primalisten auf seine dreifache Größe gewachsen.\"" }
entries[200120] = { ["name"] = "Irideus' Energiekern", ["text"] = "Questgegenstand\nBenutzen: Stimmt den Energiekern auf einen Elitetitanenbewohner von Tyrhold ab und schwächt diesen.\n\"Aus den Hallen der Infusion. Dieses Gerät trieb einst den Hüter Irideus an, jetzt muss es erneut eingestimmt werden, um seinen ursprünglichen Energieausstoß wiederherzustellen.\"" }
entries[200121] = { ["name"] = "Portion Anfängerglück", ["text"] = "Benutzen: +1 Glück\n\"Ihr könnt das schaffen!\"" }
entries[200122] = { ["name"] = "Zeitfernrohr", ["text"] = "Questgegenstand\nEinzigartig\n\"Bilder aus Vergangenheit, Gegenwart und Zukunft überlappen sich, während Ihr hindurchseht.\"" }
