entries[200506] = { ["name"] = "Getriebener Setzling", ["text"] = "Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n\"Ein magischer Samen, der vor Leben vibriert.\"\nVerkaufspreis:" }
entries[200507] = { ["name"] = "Verrotteter getriebener Setzling", ["text"] = "Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n\"Ein Samen, der von der Macht des Verfalls heimgesucht wurde. In ihm scheint jedoch immer noch ein Rest Leben zu ruhen.\"\nVerkaufspreis:" }
entries[200508] = { ["name"] = "Selbstverbreitender getriebener Setzling", ["text"] = "Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n\"Die Essenz des Lebens wogt darin und versucht fortwährend, sich zu befreien.\"\nVerkaufspreis:" }
entries[200509] = { ["name"] = "Aufgebrachter getriebener Setzling", ["text"] = "Benutzen: Pflanzt den Samen in einem Stück fruchtbarem Boden auf den Dracheninseln. Fruchtbarer Boden befindet sich oft in der Nähe von Gebieten, die direkt mit den Drachenschwärmen in Verbindung stehen. Wer weiß, was darauf wächst?\nBenötigt Kräuterkunde der Dracheninseln (1)\n\"Der Samen hat eine bedrohliche Aura. Möglicherweise müsst Ihr für ihn Verbündete versammeln.\"\nVerkaufspreis:" }
