entries[200548] = { ["name"] = "Schlüssel zu Maldras Fesseln", ["text"] = "Questgegenstand\n\"Orian Dunkelwasser hat Malda angekettet. Dieser Schlüssel könnte sie befreien.\"" }
entries[200549] = { ["name"] = "Restauriertes Titanenartefakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Intelligenz\nBenutzen: Gewährt einem Verbündeten aus großer Distanz einen Schild in Höhe von bis zu 37740 und gewährt Euch bis zu 5726 Geschwindigkeit. Der Absorptions- und Geschwindigkeitswert variiert abhängig von der Distanz zwischen Euch und Eurem Ziel. Je näher Ihr einander seid, desto höher der Absorptionswert und desto niedriger der Geschwindigkeitswert. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[200550] = { ["name"] = "Sehr bequemer Pelz", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Macht es Euch bequem wie die Maruuk! (20 Min Abklingzeit)\nBenötigt Ruhmrang 3 bei den Zentauren der Maruuk und den Abschluss der Quest \"Kultureller Austausch\".\nVerkaufspreis:" }
entries[200551] = { ["name"] = "Bequemer Pelzstapel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruht Euch wie die Khanam aus, egal, wo Ihr seid! (20 Min Abklingzeit)\nBenötigt Ruhmrang 3 bei den Zentauren der Maruuk und den Abschluss der Quest \"Kultureller Austausch\".\nVerkaufspreis:" }
entries[200552] = { ["name"] = "Hülle des Schwallrufers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Stärke\nBenutzen: Kanalisiert Ströme um Euch herum, die Gegnern in der Nähe im Verlauf von 3 Sek. [ 1906 * (6) * (1 + Vielseitigkeit)] Naturschaden zufügen. Löst dann eine mächtige Explosion aus, die 53355 Naturschaden verursacht, der zwischen allen Gegnern in der Nähe aufgeteilt wird. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[200553] = { ["name"] = "Panthisnektar", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt den Panthisnektar Euren Vorräten der Dracheninseln hinzu.\n\"Die schalenförmige Blume bildet eine Vertiefung, in der sich Nektar sammelt. Dank seines hohen Zuckergehalts ist der Nektar eine begehrte Kochzutat.\"\nVerkaufspreis:" }
entries[200554] = { ["name"] = "Tropfkappenhut", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt den öligen Tropfkappenhut Euren Vorräten der Dracheninseln hinzu.\n\"Die Tropfkappe sondert eine ölige Substanz ab, wenn sie reift. Als Brandbeschleuniger ist dieses Öl ein gefragtes und kostbares Gut.\"\nVerkaufspreis:" }
entries[200555] = { ["name"] = "Infernosamen", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Infernosamen Euren Vorräten der Dracheninseln hinzu.\n\"Ähnlich wie Schießpulver explodieren die Infernokapseln, wenn sie vollständig gereift sind, und verstreuen so ihre Samen. Die Djaradin sammeln sie, während sie gerade erst blühen, und nutzen sie später, um ihre Schmieden auf Schmelztemperatur zu bringen.\"\nVerkaufspreis:" }
entries[200556] = { ["name"] = "Verzaubertes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Irrwische aus arkaner Magie wirbeln in dem verzauberten Gefäß umher.\"" }
entries[200557] = { ["name"] = "Verzaubertes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Irrwische aus arkaner Magie wirbeln in dem verzauberten Gefäß umher.\"" }
entries[200558] = { ["name"] = "Verzaubertes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Irrwische aus arkaner Magie wirbeln in dem verzauberten Gefäß umher.\"" }
entries[200559] = { ["name"] = "Säbel des Kobaltduellisten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nBenötigt das maximale Energieniveau des Kobaltkonvents.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[200560] = { ["name"] = "Verzaubertes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Irrwische aus arkaner Magie wirbeln in dem verzauberten Gefäß umher.\"" }
entries[200561] = { ["name"] = "Tiefwasserköder", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Entzieht besiegten Wasserelementaren Essenz." }
entries[200563] = { ["name"] = "Urzeitliche Ritualmuschel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Führt das Beschwörungsritual aus und haltet Zwiesprache mit einer der Urschildkröten, um ihren Segen zu erhalten.\n\nDie Ritualstelle befindet sich südlich des Piers von Uktulut an der Küste des Erwachens, nahe der Überreste eines Drachen.\nVerkaufspreis:" }
entries[200586] = { ["name"] = "Heruntergekommene Sonnenbrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n70 ( 70)\n\"Dieses modische Accessoire wurde durch die Zeit im Bad der Ruhigen Träume sehr beschädigt, aber vielleicht hat es für einen der Gäste einen sentimentalen Wert.\"" }
entries[200587] = { ["name"] = "Ledergebundene Expeditionsnotiz", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses fest zusammengerollte Pergament wurde in rissiges, gefärbtes Leder eingewickelt. Auf der Bindung erkennt man die Initialen T und S.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200588] = { ["name"] = "Fleischiger Stängel", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt den fleischigen Stängel Euren Vorräten der Dracheninseln hinzu.\n\"Die Stacheln sind ein Zeichen dafür, dass die Pflanze reift, und sollen das proteinreiche Fleisch am Stängel schützen.\"\nVerkaufspreis:" }
entries[200589] = { ["name"] = "Hydrolebenssamen", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt Hydrolebenssamen Euren Vorräten der Dracheninseln hinzu.\n\"Lebenssamen werden an den Lebensbecken gezüchtet, denn wenn man sie zusammen mit anderen Samen anpflanzt, verzehnfacht sich deren Wachstum.\"\nVerkaufspreis:" }
entries[200590] = { ["name"] = "Sorgfältig zusammengerollte Nachricht", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Rolle wurde so fest zusammengerollt, dass sie sich kaum entrollen lässt.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200592] = { ["name"] = "Dreckiger alter Ranzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet den Beutel und offenbart den Inhalt.\n\"Ein zerbröckeltes, verblichenes Siegel der Drachenschuppenexpedition befindet sich auf dem Knopf an der Lasche des Ranzens.\"\nVerkaufspreis:" }
entries[200593] = { ["name"] = "Versiegelte Expeditionsnotiz", ["text"] = "Wird beim Aufheben gebunden\n\"Unterschrieben und versiegelt durch die Drachenschuppenexpedition.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200594] = { ["name"] = "Thaelins zweitliebster Kamm", ["text"] = "Wird beim Aufheben gebunden\n\"Eignet sich perfekt selbst für die struppigsten Zwergenbärte.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200595] = { ["name"] = "Duftendes Pergament", ["text"] = "Wird beim Aufheben gebunden\n\"Was auch immer auf dem Pergament geschrieben stand, wurde durch Wasser hinfortgewaschen und hinterließ einen einzigartigen Duft und verwaschene Schriftzeichen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200596] = { ["name"] = "Brief von Thaelin Schwarzamboss", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Brief wurde auf frischem Pergament verfasst und mit dem Siegel der Drachenschuppenexpedition versehen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200597] = { ["name"] = "Strauß der Liebenden", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft den Strauß der Liebenden einem Freund oder einer Freundin zu. (5 Min Abklingzeit)\n\"Wer ist als Nächstes dran?\"" }
entries[200598] = { ["name"] = "Meluuns grünes Curry", ["text"] = "Questgegenstand\nEinzigartig\n\"Großzügige Fischstückchen sind eingetaucht in die einzigartigen Aromen aus Moschushirschsahne, Grünbeere und herzhaften Gewürzen.\"" }
entries[200599] = { ["name"] = "Technik: Drakonisches Schreiben der Genialität", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein drakonisches Schreiben der Genialität herstellt.\nBenötigt Inschriftenkunde der Dracheninseln (35)\nBenötigt die Rufstufe \"Bevorzugt\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
