entries[200603] = { ["name"] = "Technik: Drakonisches Schreiben der Finesse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein drakonisches Schreiben der Finesse herstellt.\nBenötigt Inschriftenkunde der Dracheninseln (35)\nBenötigt die Rufstufe \"Bevorzugt\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
entries[200604] = { ["name"] = "Technik: Drakonisches Schreiben der Wahrnehmung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein drakonisches Schreiben der Wahrnehmung herstellt.\nBenötigt Inschriftenkunde der Dracheninseln (35)\nBenötigt die Rufstufe \"Bevorzugt\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
entries[200605] = { ["name"] = "Technik: Drakonisches Schreiben der Gewandtheit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein drakonisches Schreiben der Gewandtheit herstellt.\nBenötigt Inschriftenkunde der Dracheninseln (35)\nBenötigt die Rufstufe \"Bevorzugt\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
entries[200606] = { ["name"] = "Karte eines Vorbesitzers", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Karte wurde aus Tierhaut gefertigt und zeigt den bereits abgehakten Fundort eines Schatzes, der ursprünglich durch ein \"X\" markiert war.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[200607] = { ["name"] = "Halb aufgegessene Banane", ["text"] = "Wird beim Aufheben gebunden\n\"Warm und weich. Die Bissspuren sehen sehr klein aus.\"\nVerkaufspreis:" }
entries[200609] = { ["name"] = "Drachenrennenpreisgeld - Erster Platz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kleine Belohnung für eine gute Platzierung im Rennen.\"\n<Zum Öffnen rechtsklicken>" }
entries[200610] = { ["name"] = "Drachenrennenpreisgeld - Zweiter Platz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kleine Belohnung für eine gute Platzierung im Rennen.\"\n<Zum Öffnen rechtsklicken>" }
entries[200611] = { ["name"] = "Drachenrennenpreisgeld - Dritter Platz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine kleine Belohnung für eine gute Platzierung im Rennen.\"\n<Zum Öffnen rechtsklicken>" }
entries[200613] = { ["name"] = "Windsteinfragment der Aylaag", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Kehrt zum Lager der Aylaag zurück, wo immer es sein mag. Nicht verfügbar, während der Klan sich bewegt. (15 Min Abklingzeit)\n5 Aufladungen\nBenötigt Ruhmrang 11 bei den Zentauren der Maruuk und den Abschluss der Quest \"Pfeifende Steine\".\n\"Eine kleine Menge des Segens der Winde, gerade genug, um ein Flüstern und den Flüsternden zu tragen.\"" }
entries[200617] = { ["name"] = "Zerschmetterndes Totem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Ihr lasst die Erde am Zielort beben und brechen, wodurch Gegner in einem Umkreis von 10 Metern alle 1 Sek. Naturschaden erleiden. Hält 10 Sek. lang an.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (8 Sek. Abklingzeit)\n\"Ein mächtiges Totem, das von Erdheiler Govrum erschaffen wurde.\"\nVerkaufspreis:" }
entries[200619] = { ["name"] = "Scaralesh Spezial", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 42188 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Mit geschmorten Chilischoten, edlem Wein, Krabbenfleischimitat und dem Einfallsreichtum der Dracthyr angerichtet.\"\nVerkaufspreis:" }
entries[200620] = { ["name"] = "Entflammendes Räucherwerk", ["text"] = "Verkaufspreis:" }
