entries[200622] = { ["name"] = "Fokussierendes Räucherwerk", ["text"] = "Verkaufspreis:" }
entries[200623] = { ["name"] = "Windgewachsenes Gras", ["text"] = "\"Ohn'ahras Winde stärken das Gras auf den Ebenen.\"\nVerkaufspreis:" }
entries[200628] = { ["name"] = "Einigermaßen stabilisiertes Arkana", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört außerhalb des Kobaltkonvents eine Arkanakugel. (1 Stunde Abklingzeit)\n\"Instabile Energien bemühen sich, möglichst stabil zu erscheinen, weil Ihr es von ihnen erwartet.\"" }
entries[200630] = { ["name"] = "Ruhestein des Windweisen der Ohn'ir", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück zu Eurem Heimatort: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Kehrt mit Ohn'ahras Anmut nach Hause zurück.\"" }
entries[200631] = { ["name"] = "Fetzige Tuskarrparty", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zeigt Euren Tuskarrfreunden Eure besten Tanzschritte! (30 Min Abklingzeit)\n\"Nach einem anstrengenden Tag voller geretteter Leben bleibt nur noch eins: eine Tanzparty der Tuskarr!\"" }
entries[200635] = { ["name"] = "Kräuter der Dracheninseln verfeinern", ["text"] = "\"Verfeinert Kräuter, die Ihr auf den Dracheninseln gesammelt habt, zu höherer Qualität.\"" }
entries[200636] = { ["name"] = "Quintessenz der urzeitlichen Beschwörung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Führt eine elementare Beschwörung durch und verwandelt Euch für 20 Min. in das beschwörte Elementar.\nVerkaufspreis:" }
entries[200637] = { ["name"] = "Talisman der Maruuk", ["text"] = "\"Ein Symbol der Zentauren der Maruuk.\"\nVerkaufspreis:" }
entries[200638] = { ["name"] = "Blasenerfüllte Flunder", ["text"] = "Einzigartig\n\"Ein seltener und ungewöhnlicher Fisch von nur geringem Wert.\"\nVerkaufspreis:" }
entries[200639] = { ["name"] = "Talisman von Ohn'ahra", ["text"] = "\"Ein Symbol der wilden Göttin Ohn'ahra.\"\nVerkaufspreis:" }
entries[200640] = { ["name"] = "Obsidianeigelege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Platziert drei Obsidiandracheneier, die zum Ausschlüpfen bereit sind, auf dem Boden! (15 Min Abklingzeit)\nHierfür muss Sabellian Euch als Vasall betrachten.\n\"Die Welt ist womöglich noch nicht bereit für diese Drachen.\"\nVerkaufspreis:" }
entries[200641] = { ["name"] = "Verzauberter Krümmrindenzauberstab", ["text"] = "Wird beim Anlegen gebunden\nDistanz Zauberstab\n41 - 69 Schattenschaden Geschwindigkeit 2.00\n(27.5 Schaden pro Sekunde)\n+283 Intelligenz\n+73 Ausdauer\n+ 49 Zufallswert 1\n+ 49 Zufallswert 2\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[200642] = { ["name"] = "Fackel des urtümlichen Erwachens", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n109 - 182 Feuerschaden Geschwindigkeit 2.00\n(72.8 Schaden pro Sekunde)\n+748 Intelligenz\n+208 Ausdauer\n+ 120 Zufallswert 1\n+ 120 Zufallswert 2\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[200646] = { ["name"] = "Netz des bärbeißigen Fischers", ["text"] = "Questgegenstand\nEinzigartig" }
entries[200647] = { ["name"] = "Kristallschmettern", ["text"] = "\"Zerschmettert ein Verzauberungsreagenz in 3 weniger seltene Exemplare.\"" }
entries[200648] = { ["name"] = "Elementarschmettern", ["text"] = "\"Zerschmettert einen erweckten Elementar, um seine Macht zu erhalten.Kann nur auf den Dracheninseln durchgeführt werden.\"" }
entries[200652] = { ["name"] = "Alchemistische Aromatasche", ["text"] = "Optionales Handwerksmaterial\n+25 Rezeptschwierigkeit\nGewährt die folgende Eigenschaft: Verlängert 'Satt' durch Mahlzeiten der Dracheninseln um 100%. Effekt hält über den Tod hinaus an.\nBenutzbar mit: Rezepte der Dracheninseln für die meisten schmucklosen, epischen Ausrüstungsteile.\n\"Eine Erfindung der Tuskarr, um ihre Festmahle länger frisch zu halten.\"\nVerkaufspreis:" }
entries[200653] = { ["name"] = "Azurstab von Arkana", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n4 - 7 Schaden Geschwindigkeit 3.60\n(1.5 Schaden pro Sekunde)\n+20 Intelligenz\n+7 Ausdauer\n+ 5 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 85 / 85\nKlassen: Rufer\nVerkaufspreis:" }
