entries[200666] = { ["name"] = "Sturmverzauberter Stab", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n4 - 7 Schaden Geschwindigkeit 3.60\n(1.5 Schaden pro Sekunde)\n+20 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 85 / 85\nKlassen: Rufer\nVerkaufspreis:" }
