entries[200668] = { ["name"] = "Rabenhoffeldsichel", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+7 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 2.\nKlassen: Rufer\nVerkaufspreis:" }
entries[200669] = { ["name"] = "Smaragdstreitkolben der Träume", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+13 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 2 Vielseitigkeit\nHaltbarkeit 75 / 75\nKlassen: Rufer\nVerkaufspreis:" }
entries[200670] = { ["name"] = "Nebelberührter Portalstein", ["text"] = "Questgegenstand\n\"Fühlt sich kühl an. Während Ihr diesen Stein in Händen haltet, erfüllt das Rauschen von Wasser Eure Ohren.\"" }
entries[200671] = { ["name"] = "Irdener Portalstein", ["text"] = "Questgegenstand\n\"Scharf und kantig. Während Ihr diesen Stein in Händen haltet, ertönt ein ohrenbetäubendes Beben von sich spaltender Erde.\"" }
entries[200672] = { ["name"] = "Eisgeschmiedeter Portalstein", ["text"] = "Questgegenstand\n\"Eure Hände schrecken vor der Kälte zurück, die von diesem Stein ausgeht.\"" }
entries[200673] = { ["name"] = "Beogokas Klauen und Zähne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke]\nAnlegen: Eure schädlichen Zauber und Fähigkeiten haben eine Chance, Eurem aktuellen Ziel zusätzlich ( 6910 * 1.15) körperlichen Schaden zuzufügen. Der Schaden steigt basierend auf der fehlenden Gesundheit Eures Ziels.\nVerkaufspreis:" }
entries[200674] = { ["name"] = "Blauschnabelfleisch", ["text"] = "Questgegenstand\n\"Ein festes Stück Entenfleisch, perfekt für die Benutzung in Fallen.\"" }
entries[200675] = { ["name"] = "Bündel an Elementarüberfluss", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[200676] = { ["name"] = "Statisch aufgeladene Schuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, ermächtigende Blitze in Euch einschlagen zu lassen, die Euch 15054 Naturschaden zufügen und Euer Tempo 15 Sek. lang um 1339 erhöhen.\n\"Es gehen immer noch Funken davon aus. Was soll schon schiefgehen?\"\nVerkaufspreis:" }
entries[200677] = { ["name"] = "Traumblütenblatt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Kräuterkunde der Dracheninseln (25)" }
entries[200678] = { ["name"] = "Traumblüte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Kräuterkunde der Dracheninseln (25)\n\"Ihr vermutet, dass es ein Weilchen dauert, bis Ihr wieder eine ausgewachsene Traumblüte findet.\"" }
entries[200679] = { ["name"] = "Essenz des Schattens von Somnikus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 342.\nBenutzen: Vergiftet alle Gegner innerhalb von 8 Metern um den Zaubernden. Die Opfer des Giftes erleiden 45 Sek. lang alle 5 Sek. 12005 Naturschaden.\nGegner, die während der Vergiftung sterben, setzen eine Welle der Heilung frei, die Verbündete in der Nähe um 135111 Gesundheit heilt. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[200680] = { ["name"] = "Maruukai Mule", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\nVerkaufspreis:" }
entries[200681] = { ["name"] = "Ohn Lite", ["text"] = "Benutzen: Trinkt ein schwaches alkoholisches Getränk aus dem Horn. Wie es Tradition ist.\n\"Das Lieblingsbier der Zentauren der Maruuk. Wird traditionell in einem Jagdhorn serviert.\"\nVerkaufspreis:" }
entries[200682] = { ["name"] = "Schulterschützer aus gehärteten Schuppen", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n155 Rüstung\n+50 [Stärke oder Intelligenz]\n+75 Ausdauer\n+ 52 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 48.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[200683] = { ["name"] = "Beinschützer der tiefen Schichten", ["text"] = "Wird beim Aufheben gebunden\nBeine Platte\n729 Rüstung\n+257 [Stärke oder Intelligenz]\n+416 Ausdauer\nErhöht Eure kritische Trefferwertung um + 219.\nErhöht Eure Tempowertung um + 260.\nHaltbarkeit 120 / 120\n\"Je tiefer, desto stärker.\"\nVerkaufspreis:" }
entries[200684] = { ["name"] = "Smaragdfarbener Schwanzknochen", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n136 - 227 Schaden Geschwindigkeit 3.60\n(50.4 Schaden pro Sekunde)\n+67 Stärke\n+100 Ausdauer\nErhöht Eure kritische Trefferwertung um + 61.\nErhöht Eure Meisterschaftswertung um + 73.\nHaltbarkeit 120 / 120\n\"Teil des Rückgrats eines grünen Drachen, das einst von einem Riesen als Dolch verwendet wurde.\"\nVerkaufspreis:" }
entries[200685] = { ["name"] = "Verzauberter Kompass", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt den verzauberten Kompass Euren Vorräten der Dracheninseln hinzu.\n\"Er zeigt nicht nach Norden, sondern besteht stur darauf, Euch in eine ganz bestimmte Richtung zu lotsen.\"\nVerkaufspreis:" }
entries[200686] = { ["name"] = "Urfokus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 10 Urfokusse, um eine urzeitliche Infusion zu erschaffen.\nHandwerksmaterial\n\"Wird verwendet, um ein optionales Reagenz für die Herstellung von heroischer Ausrüstung zu erschaffen.\"\nVerkaufspreis:" }
entries[200687] = { ["name"] = "Sturmschiefermanschetten", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Stoff\n162 Rüstung\n+208 Intelligenz\n+532 Ausdauer\n+ 112 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 249.\nHaltbarkeit 55 / 55\nVerkaufspreis:" }
entries[200688] = { ["name"] = "Strümpfe der wirbelnden Winde", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n488 Rüstung\n+369 [Beweglichkeit oder Intelligenz]\n+946 Ausdauer\nErhöht Eure kritische Trefferwertung um + 216.\n+ 427 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[200689] = { ["name"] = "Frostklauenband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+234 Ausdauer\n+ 329 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 391.\n\"Elementarenergie schlummert darin und wartet darauf, dass ein Tarasek von ihr Gebrauch macht.\"\nVerkaufspreis:" }
entries[200690] = { ["name"] = "Ritheremblütenblätter", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Ritheremblütenblätter Euren Vorräten der Dracheninseln hinzu.\n\"Zu einem feinen Pulver gemahlen, dienen die Blätter der Ritheremblüte als natürliches Gerinnungsmittel.\"\nVerkaufspreis:" }
entries[200691] = { ["name"] = "Klauendisteldornen", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Klauendisteldornen Euren Vorräten der Dracheninseln hinzu.\n\"Die Dornenspitzen verfügen über ein natürliches Betäubungsmittel, das von den Maruuk für medizinische Behandlungen verwendet wird.\"\nVerkaufspreis:" }
entries[200692] = { ["name"] = "Geschenk des Hains", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt das Geschenk des Hains Euren Vorräten der Dracheninseln hinzu.\n\"Das Extrakt dieser Pflanze kann verwendet werden, um die Effektivität von Verbänden zu erhöhen, wodurch größere Schnitte und Abschürfungen schneller heilen.\"\nVerkaufspreis:" }
entries[200693] = { ["name"] = "Teratablätter", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Teratablätter Euren Vorräten der Dracheninseln hinzu.\n\"Das Öl in den Blättern der Teratapflanze kann zum Behandeln von Verbrennungen verwendet werden.\"\nVerkaufspreis:" }
entries[200694] = { ["name"] = "Flussglöckchenknollen", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Flussglöckchenknollen Euren Vorräten der Dracheninseln hinzu.\n\"Die belebenden Wasser des Flusses von Ohn'ahra versorgen die Knollen mit natürlichen Mineralien. Sie werden auf den Ebenen gemeinhin für ihren Vitamingehalt geschätzt.\"\nVerkaufspreis:" }
entries[200695] = { ["name"] = "Fangzähnchenblütenblätter", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Fangzähnchenblütenblätter Euren Vorräten der Dracheninseln hinzu.\n\"Die Zentauren der Ebenen nutzen eine Paste, die aus den Blütenblättern des extrem giftigen Fangzähnchens hergestellt wird, um ihre Pfeilspitzen für die Jagd auf große Beute mit Gift zu versehen.\"\nVerkaufspreis:" }
entries[200696] = { ["name"] = "Winterbeeren", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Winterbeeren Euren Vorräten der Dracheninseln hinzu.\n\"Diese Beeren gedeihen im kalten Klima des Azurblauen Gebirges. Sie enthalten viel Zucker und werden überall auf den Dracheninseln gehandelt.\"\nVerkaufspreis:" }
entries[200697] = { ["name"] = "Pestling", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt den Pestling Euren Vorräten der Dracheninseln hinzu.\n\"Dieser aus der Seuche erwachsene Pilz ist in größeren Mengen giftig, aber in kleinen, kontrollierten Dosen dient er als wirksames Schmerzmittel.\"\nVerkaufspreis:" }
entries[200698] = { ["name"] = "Leykugel", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Leykugel Euren Vorräten der Dracheninseln hinzu.\n\"Wenn sie kurz vor der Reife geerntet wird, kann die Kugel zu einem Pulver zerstoßen werden, das einen schillernden und ablenkenden Nebel erzeugen kann.\"\nVerkaufspreis:" }
entries[200699] = { ["name"] = "Seidenpflanzenfasern", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Seidenpflanzenfasern Euren Vorräten der Dracheninseln hinzu.\n\"Werden zum Isolieren von Kleidung oder Wohnräumen in kalten Umgebungen genutzt.\"\nVerkaufspreis:" }
entries[200700] = { ["name"] = "Zypressenbeeren", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Zypressenbeeren Euren Vorräten der Dracheninseln hinzu.\n\"Die Öle der beerenartigen Zapfen werden häufig als harntreibendes Mittel genutzt, können aber auch zu Alkohol mit Kiefernnote destilliert werden.\"\nVerkaufspreis:" }
entries[200701] = { ["name"] = "Tizianextrakt", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt das Tizianextrakt Euren Vorräten der Dracheninseln hinzu.\n\"Dieses kräftige Rotgoldpigment wird fast ausschließlich für titanische Architektur und Freilichtmalerei verwendet.\"\nVerkaufspreis:" }
entries[200702] = { ["name"] = "Purpurtizianextrakt", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt das Purpurtizianextrakt Euren Vorräten der Dracheninseln hinzu.\n\"Eine Variante der klassischen Tizianorchidee, die selektiv gezüchtet werden muss, um ihre purpurne Farbe zu erhalten.\"\nVerkaufspreis:" }
entries[200703] = { ["name"] = "Rankenblumenfasern", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Rankenblumenfasern Euren Vorräten der Dracheninseln hinzu.\n\"Die Fasern der Rankenblume sind flexibel und robust. Flechtet man genug von ihnen zu einem Strang, erhält man ein hervorragendes Seil.\"\nVerkaufspreis:" }
entries[200704] = { ["name"] = "Gratonasamen", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Gratonasamen Euren Vorräten der Dracheninseln hinzu.\n\"Wenn sie zu einer Paste zerstoßen werden, können die freigesetzten Öle als Feuchtigkeitsspender für geschuppte Wesen dienen.\"\nVerkaufspreis:" }
entries[200705] = { ["name"] = "Thaldraszuswurzel", ["text"] = "Vorräte der Dracheninseln\nWird beim Aufheben gebunden\nFügt die Thaldraszuswurzel Euren Vorräten der Dracheninseln hinzu.\n\"Zu feinem Tee gemahlen kann sie als Schlafmittel genutzt werden, bei höherer Dosierung dient sie sogar als Betäubungsmittel für medizinische Zwecke.\"\nVerkaufspreis:" }
entries[200707] = { ["name"] = "Schrank der endlosen Umhänge", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ihr habt Zugriff auf Furorions persönlichen Kleiderschrank. (15 Min Abklingzeit)\nHierfür muss Furorion Euch als Vasall betrachten.\n\"Wenn Ihr den Schwarzen Prinzen trefft, müsst Ihr ein angemessenes Bild abgeben.\"\nVerkaufspreis:" }
entries[200708] = { ["name"] = "Polymorpher Umhang der Absorption", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 3 Vielseitigkeit\nVerkaufspreis:" }
