entries[200884] = { ["name"] = "Ensemble: Kettenrüstung des glorreichen Drachenreiters", ["text"] = "Wird an Kriegsmeute gebunden\nKlassen: Jäger , Schamane , Rufer\nBenutzen: Sammelt die Vorlagen des Kettenrüstungssets des glorreichen Drachenreiters.\n\"Gold und Rot kennzeichnen einen Drekirjar von unvergleichlicher Kraft.\"" }
entries[200885] = { ["name"] = "Zimtiger Aschenblütentee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Aus funkenschlagenden Blütenblättern vom Hyjal gebrüht, sorgt dieses Gebräu dafür, dass auch Eure Schritte ordentlich Funken schlagen. Erhöht die Bewegungsgeschwindigkeit 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200886] = { ["name"] = "Zitroniger Silberblatttee", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Dieses klassische Gebräu aus den Östlichen Königreichen sorgt für ein ordentliches und korrektes Gefühl.\nVerkaufspreis:" }
entries[200887] = { ["name"] = "Rauchiger Portwein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Ein loagesegneter Krug rauchigen Portweins, mit dem Ihr Euer fleischhaltiges Mahl runterspülen könnt. Erhöht die Hauptwert 1 Stunde lang um 10%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200888] = { ["name"] = "Kohlebefeuerte Rippchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Die Garung über einem Bett aus Ankerkraut, Sirenenpollen und frischen Vorquinkohlen erzeugt einen deftigen Geschmack, der Euch ein durchdringendes Erlebnis bietet! Erhöht die Ausdauer 1 Stunde lang um 20%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200889] = { ["name"] = "Stark gewürzte Keule", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Eine köstliche Terrorhornkeule, großzügig mit gemahlenem Akundas Biss eingerieben, füllt Euren Wanst. Ihr spürt plötzlich die Macht eines großen Kriegers in Euch!\nVerkaufspreis:" }
entries[200890] = { ["name"] = "Steinkrallenblütenspieß", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Ein Spieß mit leicht gegrilltem und frisch gewürztem Gemüse direkt von den Höfen der Bluthufe in Kalimdor. Erhöht die Manaregeneration 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200891] = { ["name"] = "Druidischer Traumsalat", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Nachthafenbeeren auf einem Bett geiststärkenden Gemüses. Erfüllt Euch mit dem Ruhm, Leben sprießen zu lassen, wo immer Ihr wandelt!\nVerkaufspreis:" }
entries[200892] = { ["name"] = "Drachenfruchtpunsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Lehnt Euch zurück und genießt eine Tasse mit den besten Früchten und Beeren der Dracheninseln auf dieser Seite der Kaskaden. Verringert die Fallgeschwindigkeit.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200893] = { ["name"] = "Poschierter azsunianscher Hummer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Kräftiger Nor'danilhummer, nach traditioneller Art der Verheerten Inseln pochiert und eingelegt. Erhöht alle Werte 1 Stunde lang um 5%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200894] = { ["name"] = "Seltener Jahrgangsarkwein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Die süßen, tanninbetonten Noten dieses Arkweins singen von Suramar, während Eure Sinne geschärft werden. Erhöht den kritischen Schaden 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200895] = { ["name"] = "Feine Taladorkäseplatte", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Aus der Milch von draeneiischen, orchideengefütterten Talbuks, Grollhufen und Elekk. Ein wunderbar strenger Geruch verschiedener wohlgereifter Käsesorten erfüllt die Luft!\nVerkaufspreis:" }
entries[200896] = { ["name"] = "Karamellisierter Wels des Kapitäns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Knusprig gebackener Bronhavnwels, der würdig wäre, der Familie Prachtmeer kredenzt zu werden. Erhöht die Rüstung 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200897] = { ["name"] = "Venriks Ziegenmilch", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Selbst ohne den traditionellen Totenkopfkrug fühlt Ihr Euch damit wie ein wahrer Freihafenpirat!\nVerkaufspreis:" }
entries[200898] = { ["name"] = "Mantisgarnelencocktail", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: In Zitrone marinierte Mantisgarnelen aus Binan in einer würzigen Glühmagensauce. Gewährt Wasseratmung.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200899] = { ["name"] = "Gebratene Meeresnebelnudeln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Heiße Meeresnebelnudeln frisch aus der Pfanne, garniert mit fein gewürfeltem Gemüse und Wurzeln aus Pel'zin. Erhöht das Tempo 1 Stunde lang um 10%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200900] = { ["name"] = "Frittierte Kaisertaschen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: In pandarischen Ölen und Gewürzen knusprig gebratener Kaiserlachs in Taschen aus frisch gemahlenem Zandalarimehl. Erhöht die Meisterschaft 1 Stunde lang um 20%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200901] = { ["name"] = "Mit Roquefortkäse gefüllte Paprika", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Scharfe Krasarangpaprika gefüllt mit reifem Roquefortkäse von den kräutergrasenden Ziegen Seenhains.\nVerkaufspreis:" }
entries[200902] = { ["name"] = "Rabenbeerenpanacotta", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Eine seidig-süße Leckerei aus gebackenen Käsen und Mildenhallhonig, übergossen mit einem dicken Rabenbeerensirup. Erhöht die Angriffskraft 1 Stunde lang um 10%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200903] = { ["name"] = "Moiras Lieblingsespresso", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Über geschmolzenen Flammen geröstet, zusammen mit Brombeeren gebrüht und mit Malz gemischt. Da ist es nicht verwunderlich, dass es sich dabei um die Lieblingsmischung der regierenden Königin handelt! Erhöht das Angriffstempo 1 Stunde lang um 30%.\n\nNur auf den Dracheninseln aktiv.\nVerkaufspreis:" }
entries[200904] = { ["name"] = "Pikanter Pomfruchtkuchen", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Frische Pomfrüchte aus Kun-Lai gemischt mit scharfem Zucker aus den Tiefen der Schattenschmiede.\n\nEinfach köstlich!\nVerkaufspreis:" }
