entries[200938] = { ["name"] = "Leerer Seelenkäfig", ["text"] = "\"Von Juwelenschleifern gefertigt, um mit dem von Ingenieuren hergestellten schockdrosselnden Seeleninhalierer benutzt zu werden. Mit ihm können Elementarseelen eingefangen werden, um sie später in vielen mächtigen Fertigungen zu verwenden. Sie können auch brutal zerschmettert werden, um erweckte Essenzen zu erhalten.\"\nVerkaufspreis:" }
